LogicDefinition.ScriptText:
#load "reference"

//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//                                                                                                          //
//    Logik:           SafetyDoorAsi                                                                        //
//                                                                                                          //
//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//
//    Datum            Version        Autor            Beschreibung
//
//    10.06.2025       1.3.0          Greif            Header integriert
//
//============================================================================================================
//
//    SW-Standard      Geprüft        Prüfer           Allgemeine Informationen
//                     
//    FEE              X              Greif            Schutztüre mit AS Interface
/*
//============================================================================================================
//
//    Beschreibung:
//
//    Die Logik simuliert einen Schutztürschalter mit AS Interface.
//    Über den Eingang (PLC_OUT_UnlockDoor=1) wird die Schutztüre entriegelt und mit dem Eingang
//    (SIM_Cabinet_OpenDoor=1) geöffnet. Dies wird an den Ausgängen (PLC_IN_Bit0-3) mit den 4 Bits signalisiert.
//    Ausgänge: 1111 -> verriegelt
//              1100 -> entriegelt
//              0000 -> geöffnet
//
//============================================================================================================
//
//    Input Slot Values
//    PLC_OUT_UnlockDoor        =   Bool, Schutztüre entriegeln
//    SIM_Cabinet_OpenDoor      =   Bool, Schutztüre öffnen
//    
//    Output Slot Values
//    PLC_IN_Bit0-3             =   Bool, Schutztüre Status
//
//============================================================================================================
*/
//////////////////////////////////////////////////////////////////////////////////////////////////////////////

#region Schutztüre öffnen/schließen
//============================================================================================================
// S C H U T Z T Ü R E    Ö F F N E N / S C H L I E S S E N
//============================================================================================================

//Door opened
if(SIM_Cabinet_OpenDoor && PLC_OUT_UnlockDoor)
{
    doorOpened = true;
}
else if(!SIM_Cabinet_OpenDoor)
{
    doorOpened = false;
}

#endregion

#region Ausgänge setzen
//============================================================================================================
// A U S G Ä N G E    S E T Z E N
//============================================================================================================

// Output
if(!doorOpened && !PLC_OUT_UnlockDoor)
{
    PLC_IN_Bit0 = true;
    PLC_IN_Bit1 = true;
    PLC_IN_Bit2 = true;
    PLC_IN_Bit3 = true;
}

else if(!doorOpened && PLC_OUT_UnlockDoor)
{
    PLC_IN_Bit0 = true;
    PLC_IN_Bit1 = true;
    PLC_IN_Bit2 = false;
    PLC_IN_Bit3 = false;
}

else if(doorOpened)
{
    PLC_IN_Bit0 = false;
    PLC_IN_Bit1 = false;
    PLC_IN_Bit2 = false;
    PLC_IN_Bit3 = false;
}

#endregion
